// Ported from the Node app's Sequelize model Vehicle (first generated by tools/gen-efcore.mjs).
using System.Text.Json.Nodes;
using System.Text.Json.Serialization;
using SchoolERP.Domain.Common;

namespace SchoolERP.Domain.Entities;

/// <summary>Table <c>vehicles</c>.</summary>
public class Vehicle : AuditableEntity
{
    public int Id { get; set; }
    public string RegNo { get; set; } = null!;
    public string? Model { get; set; }
    public int Capacity { get; set; }
    public DateOnly? InsuranceExpiry { get; set; }
    public string Status { get; set; } = "active";

    [JsonIgnore]
    public ICollection<TransportStaff> TransportStaffs { get; set; } = new List<TransportStaff>();
    [JsonIgnore]
    public ICollection<TransportRoute> TransportRoutes { get; set; } = new List<TransportRoute>();
    [JsonIgnore]
    public ICollection<VehicleMaintenance> VehicleMaintenances { get; set; } = new List<VehicleMaintenance>();
    [JsonPropertyName("VehicleTracker")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public VehicleTracker? VehicleTracker { get; set; }
    [JsonIgnore]
    public ICollection<VehicleLocation> VehicleLocations { get; set; } = new List<VehicleLocation>();
}
